import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"28、【大过】 巽下兑上","description":"周易集注 - 28、【大过】 巽下兑上","frontmatter":{"title":"28、【大过】 巽下兑上","description":"周易集注 - 28、【大过】 巽下兑上"},"headers":[],"relativePath":"zh/classics/jizhu/032.md","filePath":"zh/classics/jizhu/032.md"}'),h={name:"zh/classics/jizhu/032.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_28、【大过】-巽下兑上" tabindex="-1">28、【大过】 巽下兑上 <a class="header-anchor" href="#_28、【大过】-巽下兑上" aria-label="Permalink to “28、【大过】 巽下兑上”">​</a></h1><p>大过，大者阳也，阳过于阴也。乾坤也，坎离也，山雷也，泽风也，此八卦也。干与坤错，坎与离错，泽风与山雷相错，风泽与雷山相错，六十四卦惟此八卦相错，其馀皆相综。泽本润木之物，今乃灭没其木，是大过矣。又四阳居中过盛，此所以名大过也。不然，四阳之卦亦多，何以不名过?因其居中相聚而盛，所以得名也。《序卦》“颐者养也，不养则不可动，故受之以大过”，所以次颐。</p><p>梁上屋脊之木曰栋，所以乘椽瓦者也。木曲曰桡，本未弱而栋不正，有如水之曲也。椽垂亸以渐而下曰宇，此卦大象坎，坎为栋，坎主险陷，桡之象也。又为矫輮，亦桡曲之象也。若以理论，本弱则无所承，末弱则无所寄附。此卦上缺下短，亦有桡之象。既栋桡矣，而又利有攸往，何也?盖桡以成卦之象言，利有攸往亨则以卦体卦德之占言。</p><p>《彖》曰：大过，大者过也。栋挠，本末弱也。刚过而中，巽而说行，利有攸往，乃亨。大过之时大矣哉。说音悦</p><p>以卦体卦德释卦名卦辞而叹其大。阳大阴小，本卦大者过，故名大过。本谓初，末谓上。弱者阴柔也。古人作字，本末皆从木来，木下加一画阳，取根株回煖，故为本;木上加一画阳，取枝叶向荣，故为末。刚过者，四阳也。而中者，二五也。虽三四，亦可言中，故复卦四曰中行。益卦三四皆曰中行也。巽而悦行者，内巽而外行之以悦也。若以人事论，体质本是刚毅，足以奋发有为而又用之以中，不遇于刚。德性本是巽顺，足以深入乎义理，而又行之以和，不拂乎人情，所以利有攸往，乃亨。大过之时者，言人于大过之时，行大过之事，适其时，当其事也。如尧舜禅受，汤武放伐，虽过其事而不过乎理是也。盖无其时不可过，有其时无其才亦不可过。故叹其大。与颐解革同。</p><h3 id="《象》曰-泽灭木-大过。君子以独立不惧-遁世无闷。" tabindex="-1">《象》曰：泽灭木，大过。君子以独立不惧，遁世无闷。 <a class="header-anchor" href="#《象》曰-泽灭木-大过。君子以独立不惧-遁世无闷。" aria-label="Permalink to “《象》曰：泽灭木，大过。君子以独立不惧，遁世无闷。”">​</a></h3><p>上一句大过之象，下二句大过之行，非达则不惧，穷则无闷也。穷亦有独立不惧之时，不惧者不求同俗，而求同理，天下非之而不顾也。无闷者，不求人知而求天知，举世不见知而不悔也。此必有大过人学问，义理见得明，有大过人操守，脚根立得定，方干得此事。</p><p>初六，藉用白茅，无咎。</p><p>藉者荐也，承荐其物也。因上承四刚，故曰藉。茅者，草也。巽阴木为茅，故泰卦变巽曰茅，否卦大象巽亦曰茅。巽为白，白茅之象也。无咎者，敬慎不败也。</p><p>初九当大过之时，阴柔已能慎矣。又居巽体之下，则慎而又慎者也。亦如物，不错诸地而有所藉，可谓慎矣。而又藉之以茅，茅又用夫白，白则至洁之物矣，是慎之大过者也。故有此象。然慎虽大过，以其居大过之初，虽大过而不过，故占者无咎。</p><h3 id="《象》曰-藉用白茅-柔在下也。" tabindex="-1">《象》曰：藉用白茅，柔在下也。 <a class="header-anchor" href="#《象》曰-藉用白茅-柔在下也。" aria-label="Permalink to “《象》曰：藉用白茅，柔在下也。”">​</a></h3><p>阴柔居巽之下。</p><p>九二，枯杨生稊，老夫得其女妻，无不利。</p><p>巽为杨，杨之象也。木生于泽下者，杨独多，故取此象。杨乃木之弱者，四阳之刚皆同为木，但二五近，本末之弱，故以杨言。曰枯者，取大过乎时之义，故二五皆言枯也。至三四则成干之坚刚，故言栋。稊，木稚也。二得阴在下，故言生稊。稊者下之根也。五得阴在上，故言生华。生华者，上之枝生也。根生则生生不息，枝生则无生意矣。下卦巽错震，长男也。老夫之象，故称老夫。老夫者，再娶女之夫也。应爻兑，兑乃少女也。女妻之象，故称女妻。女妻者，未嫁而幼者也。九五兑错艮，少男也。士夫之象，故称士夫。士夫乃未娶者。应爻巽为长女，老妇之象也，故称老妇。老妇者，已嫁而老者也。周公爻辞，其精至此，旧注不知象，以二五皆比于阴，殊不知九二下卦反称老夫，九五上卦反称士夫，近初者言老，近上者言少，说不通矣。</p><p>九二阳刚得中，当大过之时而应于少女，故取诸物，有枯杨生稊，取诸身有老夫得其女妻之象。可以成生育之功矣。故占者无不利。</p><h3 id="《象》曰-老夫女妻-过以相与也。" tabindex="-1">《象》曰：老夫女妻，过以相与也。 <a class="header-anchor" href="#《象》曰-老夫女妻-过以相与也。" aria-label="Permalink to “《象》曰：老夫女妻，过以相与也。”">​</a></h3><p>此庆幸之辞。言阳方大过之始，得少阴以之相与，则刚柔相济而不过，可以成生育之功矣。故占者无不利。</p><p>九三，栋桡，凶。</p><p>变坎为栋，又木坚多心，栋之象也。因坎三四皆以栋言，因巽二五皆以杨言。文王栋桡本末皆弱，周公栋桡因初之弱。</p><p>九三居内卦，下阴虚弱，下虚弱则上不正，故有栋桡之象。占者之凶，可知矣。</p><h3 id="《象》曰-栋桡之凶-不可以有辅也。" tabindex="-1">《象》曰：栋桡之凶，不可以有辅也。 <a class="header-anchor" href="#《象》曰-栋桡之凶-不可以有辅也。" aria-label="Permalink to “《象》曰：栋桡之凶，不可以有辅也。”">​</a></h3><p>同体之初，虚弱无辅助也。</p><p>九四，栋隆，吉，有它吝。</p><p>变坎，亦有栋象。隆者，隆然而高起也。它者，初也。三四皆栋，四居外卦，阴虚在上，非如三之阴虚在下也。上虚下实，则有所承载。故有栋隆之象。占者固吉矣。然下应乎初，若以柔济之，则过于柔矣。其栋决不能隆，吝之道也。故又戒占者以此。</p><h3 id="《象》曰-栋隆之吉-不桡乎下也。" tabindex="-1">《象》曰：栋隆之吉，不桡乎下也。 <a class="header-anchor" href="#《象》曰-栋隆之吉-不桡乎下也。" aria-label="Permalink to “《象》曰：栋隆之吉，不桡乎下也。”">​</a></h3><p>因外卦虚在上，实在下，所以不桡，故曰不桡乎下也。不可以有辅者，下虚故也。不桡乎下者，下实故也。</p><p>九五，枯杨生华，老妇得其士夫，无咎无誉。</p><p>兑综巽，又杨之象也。生华者，杨开花则散漫，终无益于枯也。老妇士夫，详见九二爻下。</p><p>九五以阳刚应乎过极之长女，乃时之大过而不能生育者也，故有枯杨生华，老妇得其士夫之象。占者得此，揆之于理虽无咎，而老妇反得士夫，亦非配合之美矣，安得又有誉哉。故其象占如此。</p><h3 id="《象》曰-枯杨生华-何可久也-老妇士夫-亦可丑也" tabindex="-1">《象》曰：枯杨生华，何可久也?老妇士夫，亦可丑也! <a class="header-anchor" href="#《象》曰-枯杨生华-何可久也-老妇士夫-亦可丑也" aria-label="Permalink to “《象》曰：枯杨生华，何可久也?老妇士夫，亦可丑也!”">​</a></h3><p>何可久，言终散漫。亦可丑，言非配合。言且不惟不能成生育之功，而配合非宜，亦可丑也。</p><p>上六，过涉灭顶，凶，无咎。</p><p>顶者，首也。变干为首，顶之象也。当过之时，遇兑泽之水，过涉之象也。泽水在首，灭没其顶之象也。以二阴爻论之，初藉用白茅，大过于慎者也。以其居卦之初，故不凶而无咎。上过涉灭顶，大过于济者也。以其居卦之终，故有凶而无咎。</p><p>上六处大过已极之时，勇于必济，有冒险过涉之象。然才弱不能以济，故又有灭顶之象。过涉灭顶，必杀身矣。故占者必凶。然不避艰险，慷慨赴死，杀身成仁之事也，故其义无咎。</p><h3 id="《象》曰-过涉之凶-不可咎也。" tabindex="-1">《象》曰：过涉之凶，不可咎也。 <a class="header-anchor" href="#《象》曰-过涉之凶-不可咎也。" aria-label="Permalink to “《象》曰：过涉之凶，不可咎也。”">​</a></h3><p>无咎者，上六本无咎也。不可咎者，人不得而咎之也。以人事论，过涉之凶，虽不量其浅深以取祸，然有死难之节而无茍免之羞，论其心不论其功，论是非不论利害，人恶得而咎之。</p>',36)])])}const m=e(h,[["render",t]]);export{_ as __pageData,m as default};
